{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Rates Watch Data",
    "url": "http://localhost:7803",
    "widgets_json": {
      "auction_watch": {
        "name": "Auction Watch",
        "description": "Upcoming treasury auctions.",
        "endpoint": "/auction-watch",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "staleTime": 900000,
        "runButton": true,
        "data": {
          "columnsDefs": [
            {
              "field": "auction_date",
              "headerName": "Auction Date",
              "cellDataType": "dateString"
            },
            {
              "field": "bid_to_cover",
              "headerName": "Bid To Cover",
              "cellDataType": "number"
            },
            {
              "field": "security",
              "headerName": "Security",
              "cellDataType": "text"
            },
            {
              "field": "size_bn",
              "headerName": "Size (bn)",
              "cellDataType": "number"
            }
          ]
        }
      }
    }
  }
}
